from .common import LocalBasicPage
from functools import wraps
from selenium.common.exceptions import ElementClickInterceptedException
import time


class Debug(LocalBasicPage):
    pass


def catch_interface_exception(func):
    """
    Method to catch exception and save screen shot if function raises an error
    """
    @wraps(func)
    def interface_func(*args, **kwargs):
        try:
            outcome = func(*args, **kwargs)
        except Exception:
            Debug().save_screenshot('{}'.format(func.__name__))
            raise
        return outcome
    return interface_func


def catch_intercepted_click_exception(func):
    """
    Catches ElementClickInterceptedException when button or place we want to click
    is covered by pop-up (e.g. "Nemuadmin logged in"). After 5 retries (total 15 seconds of retrying)
    method raises original exception..
    """
    @wraps(func)
    def interface_func(*args, **kwargs):
        for retries in range(6):
            try:
                outcome = func(*args, **kwargs)
            except ElementClickInterceptedException:
                if retries == 5:
                    raise \
                        ElementClickInterceptedException("Could not click button after 5 retries as it is covered"
                                                         " by other element.")
                time.sleep(3)
                continue
            return outcome
    return interface_func
